typedef unsigned char uint8;
struct vector3d { float x, y, z; vector3d &operator=(const vector3d &o) { x=o.x; y=o.y; z=o.z; return *this; } };
inline float dot(const vector3d &a, const vector3d &b) { return a.x*b.x+a.y*b.y+a.z*b.z; }
extern float *fast_acos_lookup_table;
inline float fast_acos(float a) { return fast_acos_lookup_table[(int)((a+1.0f)*512.0f)]; }
struct po { vector3d non_affine_slow_xform(const vector3d &) const __asm__("non_affine_slow_xform__C2poRC8vector3d"); };
extern vector3d ZVEC;
struct entity { char pad[48]; vector3d abs_position; const vector3d &get_abs_position() const { return abs_position; } };
struct SurfBoardObjectClass {
  char pad0[3392]; int state; char pad1[12]; entity *my_board; char pad2[140]; int current_region; char pad3[28]; int TurnType;
  vector3d GetForwardDir() { return my_board_po()->non_affine_slow_xform(ZVEC); }
  po *my_board_po() { return *(po **)((char *)my_board + 80); }
  int GetWaveRegion() { return current_region; }
  int GetBoardState() { return state; }
  int GetTurnType() { return TurnType; }
};
struct kellyslater_controller {
  char pad[48]; int state; char pad2[3356]; SurfBoardObjectClass my_board_controller;
  int get_current_state() const { return state; }
  SurfBoardObjectClass &get_board_controller() { return my_board_controller; }
};
enum { STATE_LEFTTURN=28, STATE_RIGHTTURN=61, STATE_STAND=74, GRAB_TURN=2, CARVE_TURN=15, BOARD_TURN_LEFT=5 };
class CarveManager {
  void ParseCarveInfo() __asm__("ParseCarveInfo__12CarveManager");
  void DetermineTrick(int, int);
  struct CarveNode { float time; float angle; vector3d board_vec; vector3d position; uint8 state; char pad[3]; int region; };
  float board_angle; vector3d cur_board_vec; vector3d last_board_vec;
  int TurnType; int Head; int Tail; float angle; float time; float last_record_time; int hardest_region;
  kellyslater_controller *ksctrl;
public:
  void FrameAdvance(float dt, bool force_update=false);
  void SetInternalVars() __asm__("SetInternalVars__12CarveManager");
  CarveNode CarveArray[20];
};
void CarveManager::FrameAdvance(float dt, bool force_update)
{
  float record_delta = 0.075f;
  int state = ksctrl->get_current_state();
  bool correct_state = ((state == STATE_LEFTTURN) || (state == STATE_RIGHTTURN) || (state == STATE_STAND));
  int tType = ksctrl->get_board_controller().GetTurnType();
  if ((TurnType != CARVE_TURN) && (tType == CARVE_TURN) && correct_state)
    SetInternalVars();
  else if ((TurnType != GRAB_TURN) && (tType == GRAB_TURN) && correct_state)
    SetInternalVars();
  else if (!correct_state || ((tType != CARVE_TURN) && (tType != GRAB_TURN)))
    return;

  TurnType = tType;
  last_board_vec = cur_board_vec;
  cur_board_vec = ksctrl->get_board_controller().GetForwardDir();
  int sign = CarveArray[Tail].state = ksctrl->get_board_controller().GetBoardState();
  float f_sign = (sign == BOARD_TURN_LEFT?1.0f:-1.0f);
  float dot_p = dot(cur_board_vec, last_board_vec);
  if (dot_p > 1.0f)
    dot_p = 1.0f;
  else if (dot_p < -1.0f)
    dot_p = -1.0f;

  angle += f_sign*fast_acos(dot_p);

  time += dt;
  if (force_update || ((time - last_record_time) > record_delta))
  {
    last_record_time = time;
    CarveArray[Tail].board_vec = cur_board_vec;
    CarveArray[Tail].position = ksctrl->get_board_controller().my_board->get_abs_position();
    CarveArray[Tail].time = time;
    CarveArray[Tail].state = ksctrl->get_board_controller().GetBoardState();
    CarveArray[Tail].angle = angle;
    CarveArray[Tail].region = ksctrl->get_board_controller().GetWaveRegion();

    ParseCarveInfo();
  }
}
